/**
 * UI translations — key-first dictionary.
 * Chaque clé porte ses 14 traductions ensemble. `satisfies Record<string, Tr>`
 * force la présence des 14 langues pour CHAQUE clé (le build échoue sinon).
 * Fusionné dans `translations` (voir translations.ts).
 *
 * Ordre des langues : fr, en, es, de, it, pt, nl, pl, ru, ar, zh, ja, tr, ko
 */

export type Tr = {
  fr: string; en: string; es: string; de: string; it: string; pt: string; nl: string
  pl: string; ru: string; ar: string; zh: string; ja: string; tr: string; ko: string
}

// Explicit fixed arity retains the compile-time fourteen-language guarantee.
function row(fr: string, en: string, es: string, de: string, it: string, pt: string, nl: string, pl: string, ru: string, ar: string, zh: string, ja: string, tr: string, ko: string): Tr {
  return { fr, en, es, de, it, pt, nl, pl, ru, ar, zh, ja, tr, ko }
}
function uniform(value: string): Tr {
  return row(value, value, value, value, value, value, value, value, value, value, value, value, value, value)
}

